package main

import (
	"context"
	"encoding/hex"
	"fmt"

	"github.com/4chain-ag/go-wallet-toolbox/examples/src/constants"
	"github.com/4chain-ag/go-wallet-toolbox/examples/src/core"
	"github.com/4chain-ag/go-wallet-toolbox/examples/src/method"
	sdk "github.com/bsv-blockchain/go-sdk/wallet"
)

const beefString = ""
const txid = "15f47f2db5f26469c081e8d80d91a4b0f06e4a97abcc022b0b5163ac5f6cc0c8"
const vout = 0

func main() {
	ctx := context.Background()
	env := constants.GetEnv("test")
	aliceWallet, cleanup, err := core.CreateWallet(ctx, env, env.DevKeys.AlicePrivateKey)
	if err != nil {
		cleanup()
		panic(err)
	}

	beef, err := hex.DecodeString(beefString)
	if err != nil {
		fmt.Printf("Error decoding BEEF hex: %v\n", err)
		return
	}

	paymentRemittance := core.DerivationParts().PaymentRemittance

	internalizeArgs := sdk.InternalizeActionArgs{
		Tx: beef,
		Outputs: []sdk.InternalizeOutput{
			{
				OutputIndex:       vout,
				Protocol:          "wallet payment",
				PaymentRemittance: paymentRemittance,
			},
		},
		Description: "internalize from faucet",
	}

	fmt.Printf("InternalizeArgs: %+v\n", internalizeArgs)

	result, err := methods.InternalizeTxHandler(ctx, internalizeArgs, aliceWallet)
	if err != nil {
		panic(err)
	}

	fmt.Printf("Result: %+v\n", result)
}
